    """
    Implements a basic regex matching algorithm using recursion and backtracking.
    Supports:
    - literal characters
    - '.' for any single character
    - '*' for zero or more of the preceding element
    - '+' for one or more of the preceding element
    """

    def is_match(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and p_index + 1 < len(pattern) and pattern[p_index + 1] == '*':
            # Case where '*' matches zero or more of the preceding element
            if is_match(p_index + 2, t_index):
                return True
            if t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
                return is_match(p_index, t_index + 1)
        elif p_index < len(pattern) and p_index + 1 < len(pattern) and pattern[p_index + 1] == '+':
            # Case where '+' matches one or more of the preceding element
            if t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
                if is_match(p_index, t_index + 1):
                    return True
                return is_match(p_index + 2, t_index)  # must match one then check for next
        if p_index < len(pattern) and t_index < len(text):
            if pattern[p_index] == text[t_index] or pattern[p_index] == '.':
                return is_match(p_index + 1, t_index + 1)
        return False

    return is_match(0, 0)

